ALTER TABLE parts ADD COLUMN material_group VARCHAR(20) NOT NULL DEFAULT 'UNASSIGNED' CHECK(material_group IN ('PLASTIC','METAL','ELECTRONIC','UNASSIGNED'));
UPDATE parts SET material_group='PLASTIC' WHERE material_group='UNASSIGNED' AND color_parent_id IS NULL AND (LOWER(name) LIKE '%nhựa%' OR LOWER(name) LIKE '%ốp%' OR LOWER(name) LIKE '%cốp%' OR LOWER(name) LIKE '%mặt nạ%' OR LOWER(name) LIKE '%sườn trái%' OR LOWER(name) LIKE '%sườn phải%' OR LOWER(name) LIKE '%chắn bùn%' OR LOWER(name) LIKE '%sàn để chân%' OR LOWER(name) LIKE '%phản quang%' OR LOWER(name) LIKE '%tem%');
UPDATE parts SET material_group='ELECTRONIC' WHERE material_group='UNASSIGNED' AND color_parent_id IS NULL AND (LOWER(name) LIKE '%động cơ%' OR LOWER(name) LIKE '%sạc%' OR LOWER(name) LIKE '%ic %' OR LOWER(name) LIKE '%dây nguồn%' OR LOWER(name) LIKE '%dây điện%' OR LOWER(name) LIKE '%dây đấu%' OR LOWER(name) LIKE '%dây tẩu%' OR LOWER(name) LIKE '%công tắc%' OR LOWER(name) LIKE '%tay ga%' OR LOWER(name) LIKE '%chống trộm%' OR LOWER(name) LIKE '%còi%' OR LOWER(name) LIKE '%xi nhan%' OR LOWER(name) LIKE '%chip%' OR LOWER(name) LIKE '%cổng sạc%' OR LOWER(name) LIKE '%đồng hồ%' OR LOWER(name) LIKE '%đèn%');
UPDATE parts SET material_group='METAL' WHERE material_group='UNASSIGNED' AND color_parent_id IS NULL AND (LOWER(name) LIKE '%cao su%' OR LOWER(name) LIKE '%lốp%' OR LOWER(name) LIKE '%vành%' OR LOWER(name) LIKE '%càng%' OR LOWER(name) LIKE '%giảm sóc%' OR LOWER(name) LIKE '%khóa bộ%' OR LOWER(name) LIKE '%tay phanh%' OR LOWER(name) LIKE '%bát%' OR LOWER(name) LIKE '%dây phanh%' OR LOWER(name) LIKE '%trục%' OR LOWER(name) LIKE '%lò xo%' OR LOWER(name) LIKE '%chân chống%' OR LOWER(name) LIKE '%khung xe%' OR LOWER(name) LIKE '%đỡ%' OR LOWER(name) LIKE '%tai khóa%' OR LOWER(name) LIKE '%tay xách%' OR LOWER(name) LIKE '%tay dắt%' OR LOWER(name) LIKE '%bạc%' OR LOWER(name) LIKE '%ốc%' OR LOWER(name) LIKE '%đinh%' OR LOWER(name) LIKE '%van %' OR LOWER(name) LIKE '%yên xe%' OR LOWER(name) LIKE '%ruột gà%');
UPDATE parts p SET material_group=(SELECT material_group FROM parts parent WHERE parent.id=p.color_parent_id) WHERE color_parent_id IS NOT NULL;
